// Function to switch between navigation sections
function showSection(sectionId, btnElement) {
    const sections = document.querySelectorAll('.content-section');
    sections.forEach(section => {
        section.classList.remove('active');
    });

    const buttons = document.querySelectorAll('.nav-btn');
    buttons.forEach(btn => {
        btn.classList.remove('active');
    });

    document.getElementById(sectionId).classList.add('active');

    const header = document.querySelector('header');
    if (header) {
        header.classList.toggle('beranda-bg', sectionId === 'beranda');
    }

    if (btnElement) {
        btnElement.classList.add('active');
    }
    
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

// Modal functions
const modal = document.getElementById("content-modal");
const modalTitle = document.getElementById("modal-title");
const modalText = document.getElementById("modal-text");
const modalExtra = document.getElementById("modal-extra");
const galleryContainer = document.getElementById("modal-image-gallery");
const audioPlayer = document.getElementById("story-audio");

// Kunci cerita yang termasuk kategori legenda (punya audio) dan kuliner
const LEGEND_KEYS = ["gunung_kemukus", "bayanan", "makam_butuh", "makam_putri_sukowati", "tjandra_birawa", "nyi_ageng_serang", "nyi_ageng_srenggi", "petilasan_mangkubumi", "joko_tingkir", "sangiran"];
const KULINER_KEYS = ["sego_plontang", "gablok", "balung_kethek", "sate_buntel", "nasi_tumpang", "bothok_mercon", "gatot_kerupuk", "jenang_jadah", "wajik_krasikan", "saci", "walangan", "soto_girin", "wedang_uwuh", "dawet_sragen", "wedang_ronde", "bir_pletok", "wedang_bajigur", "jus_kweni", "legen"];

function escapeHtml(str) {
    return String(str)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");
}

function openStory(storyKey) {
    const story = storiesData[storyKey];
    if (!story) return;

    // Set Title
    modalTitle.innerText = story.title;
    
    // Clear and Set Images (Visualisasi gambar terlebih dahulu)
    galleryContainer.innerHTML = "";
    (story.images || []).forEach(imgSrc => {
        const img = document.createElement("img");
        img.src = imgSrc;
        img.alt = story.title;
        img.className = "modal-img-item";
        img.loading = "lazy";
        // Sembunyikan gambar jika file tidak ditemukan
        img.onerror = function() { this.remove(); };
        galleryContainer.appendChild(img);
    });
    galleryContainer.style.display = (story.images && story.images.length) ? "flex" : "none";

    // Set Text: rapikan baris kosong berlebih, lalu tampilkan apa adanya
    // (CSS white-space: pre-line menjaga pemisah paragraf & daftar)
    modalText.textContent = story.text.replace(/\r\n/g, "\n").replace(/\n{3,}/g, "\n\n").trim();
    
    // Set Audio
    if (story.audio) {
        audioPlayer.src = story.audio;
        audioPlayer.parentElement.style.display = "block";
    } else {
        audioPlayer.pause();
        audioPlayer.removeAttribute("src");
        audioPlayer.load();
        audioPlayer.parentElement.style.display = "none";
    }

    // Konten tambahan interaktif untuk menu Pojok Aksi
    renderExtra(storyKey);
    
    modal.style.display = "block";
    modal.scrollTop = 0;
}

function renderExtra(storyKey) {
    modalExtra.innerHTML = "";
    if (storyKey === "ruang_baca") {
        renderRuangBaca();
    } else if (storyKey === "misi_jurnalis") {
        renderMisiJurnalis();
    } else if (storyKey === "catatan_kuliner") {
        renderCatatanKuliner();
    }
}

function renderRuangBaca() {
    const buildList = (keys, label) => {
        let html = `<h3 class="extra-title">${label}</h3><div class="extra-list">`;
        keys.forEach(key => {
            const s = storiesData[key];
            if (!s) return;
            html += `<button class="extra-item" onclick="openStory('${key}')">${s.audio ? "🔊" : "📖"} ${escapeHtml(s.title)}</button>`;
        });
        return html + `</div>`;
    };
    modalExtra.innerHTML = `
        <div class="extra-box">
            <p class="extra-hint">Pilih kisah atau kuliner di bawah ini untuk membaca teks, melihat gambar, dan mendengarkan audionya.</p>
            ${buildList(LEGEND_KEYS, "🗺️ Legenda & Sejarah Sragen")}
            ${buildList(KULINER_KEYS, "🍽️ Kuliner Khas Sragen")}
        </div>`;
}

function renderMisiJurnalis() {
    const file = "MISI JURNALIS CILIK.docx";
    modalExtra.innerHTML = `
        <div class="extra-box">
            <h3 class="extra-title">📄 Lembar Misi Wawancara</h3>
            <p class="extra-hint">Unduh lembar misi, cetak, lalu bawa saat mewawancarai narasumber.</p>
            <a class="action-btn download-btn" href="${encodeURI(file)}" download="${escapeHtml(file)}">⬇️ Unduh Lembar Misi (Word)</a>
        </div>`;
}

/* === CATATAN KULINERKU (Jurnal Digital, tersimpan di perangkat) === */
const JOURNAL_STORAGE_KEY = "serasi_catatan_kuliner";
const JOURNAL_FIELDS = [
    { id: "nama", label: "Nama kuliner", type: "text", placeholder: "Contoh: Sego Plontang" },
    { id: "asal", label: "Asal daerah", type: "text", placeholder: "Contoh: Sangiran, Kalijambe" },
    { id: "bahan", label: "Bahan dan cara pembuatan", type: "textarea", placeholder: "Bahan apa saja? Bagaimana cara membuatnya?" },
    { id: "rasa", label: "Rasa dan tekstur", type: "textarea", placeholder: "Manis, gurih, pedas? Kenyal, renyah, lembut?" },
    { id: "budaya", label: "Nilai budaya dan filosofi", type: "textarea", placeholder: "Kapan biasanya disajikan? Apa maknanya?" },
    { id: "refleksi", label: "Refleksi pribadi", type: "textarea", placeholder: "Apa yang kamu rasakan dan pelajari?" }
];

function loadJournal() {
    try {
        const raw = localStorage.getItem(JOURNAL_STORAGE_KEY);
        const data = raw ? JSON.parse(raw) : [];
        return Array.isArray(data) ? data : [];
    } catch (e) {
        return [];
    }
}

function saveJournal(entries) {
    try {
        localStorage.setItem(JOURNAL_STORAGE_KEY, JSON.stringify(entries));
        return true;
    } catch (e) {
        return false;
    }
}

function renderCatatanKuliner() {
    const kulinerNames = KULINER_KEYS.map(k => storiesData[k].title);
    let fieldsHtml = "";
    JOURNAL_FIELDS.forEach(f => {
        const input = f.type === "textarea"
            ? `<textarea id="journal-${f.id}" rows="3" placeholder="${escapeHtml(f.placeholder)}"></textarea>`
            : `<input type="text" id="journal-${f.id}" placeholder="${escapeHtml(f.placeholder)}" ${f.id === "nama" ? 'list="kuliner-list"' : ""}>`;
        fieldsHtml += `<label class="journal-label" for="journal-${f.id}">${f.label}</label>${input}`;
    });
    modalExtra.innerHTML = `
        <div class="extra-box">
            <h3 class="extra-title">✏️ Tulis Catatan Baru</h3>
            <p class="extra-hint">Catatan tersimpan di perangkat ini dan bisa dibuka lagi kapan saja.</p>
            <form id="journal-form" class="journal-form" onsubmit="return submitJournal(event)">
                ${fieldsHtml}
                <datalist id="kuliner-list">${kulinerNames.map(n => `<option value="${escapeHtml(n)}"></option>`).join("")}</datalist>
                <button type="submit" class="action-btn">💾 Simpan Catatan</button>
            </form>
            <div id="journal-status" class="journal-status" role="status"></div>
            <h3 class="extra-title">📚 Catatan Tersimpan</h3>
            <div id="journal-list" class="journal-list"></div>
        </div>`;
    renderJournalList();
}

function submitJournal(event) {
    event.preventDefault();
    const entry = { id: Date.now(), tanggal: new Date().toLocaleDateString("id-ID", { day: "numeric", month: "long", year: "numeric" }) };
    JOURNAL_FIELDS.forEach(f => {
        const el = document.getElementById("journal-" + f.id);
        entry[f.id] = el ? el.value.trim() : "";
    });
    const status = document.getElementById("journal-status");
    if (!entry.nama) {
        status.textContent = "Isi dulu nama kulinernya ya! 😊";
        status.className = "journal-status warn";
        return false;
    }
    const entries = loadJournal();
    entries.unshift(entry);
    if (!saveJournal(entries)) {
        status.textContent = "Maaf, catatan tidak bisa disimpan di perangkat ini.";
        status.className = "journal-status warn";
        return false;
    }
    document.getElementById("journal-form").reset();
    status.textContent = "Catatan berhasil disimpan! 🎉";
    status.className = "journal-status ok";
    renderJournalList();
    return false;
}

function renderJournalList() {
    const list = document.getElementById("journal-list");
    if (!list) return;
    const entries = loadJournal();
    if (!entries.length) {
        list.innerHTML = `<p class="extra-hint">Belum ada catatan. Ayo tulis pengalaman kulinermu yang pertama!</p>`;
        return;
    }
    list.innerHTML = entries.map(e => {
        const rows = JOURNAL_FIELDS.slice(1).filter(f => e[f.id]).map(f =>
            `<p><strong>${f.label}:</strong> ${escapeHtml(e[f.id])}</p>`).join("");
        return `
            <div class="journal-entry">
                <div class="journal-entry-head">
                    <h4>🍽️ ${escapeHtml(e.nama)}</h4>
                    <span class="journal-date">${escapeHtml(e.tanggal || "")}</span>
                </div>
                ${rows}
                <div class="journal-actions">
                    <button type="button" class="mini-btn" onclick="downloadJournalEntry(${e.id})">⬇️ Unduh</button>
                    <button type="button" class="mini-btn danger" onclick="deleteJournalEntry(${e.id})">🗑️ Hapus</button>
                </div>
            </div>`;
    }).join("");
}

function deleteJournalEntry(id) {
    if (!confirm("Hapus catatan ini?")) return;
    saveJournal(loadJournal().filter(e => e.id !== id));
    renderJournalList();
}

function downloadJournalEntry(id) {
    const e = loadJournal().find(x => x.id === id);
    if (!e) return;
    let text = `CATATAN KULINERKU - SERASI\nTanggal: ${e.tanggal || "-"}\n\n`;
    JOURNAL_FIELDS.forEach(f => { text += `${f.label}: ${e[f.id] || "-"}\n\n`; });
    const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `Catatan Kuliner - ${e.nama}.txt`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function closeModal() {
    modal.style.display = "none";
    if (audioPlayer) {
        audioPlayer.pause();
        audioPlayer.currentTime = 0;
    }
}

// Close modal when clicking outside of it
window.addEventListener("click", function(event) {
    if (event.target === modal) closeModal();
    if (event.target === quizModal) closeQuiz();
});

// Close modal with Escape key
window.addEventListener("keydown", function(event) {
    if (event.key !== "Escape") return;
    if (modal.style.display === "block") closeModal();
    if (quizModal.style.display === "block") closeQuiz();
});




