let currentQuestionIndex = 0;
let score = 0;
let isAnswered = false;
let currentQuiz = [];

const quizModal = document.getElementById('quiz-modal');
let quizQuestion = document.getElementById('quiz-question');
let quizOptions = document.getElementById('quiz-options');
const currentQNum = document.getElementById('current-q-num');
const totalQNum = document.getElementById('total-q-num');
const nextBtn = document.getElementById('next-btn');

function startQuiz() {
    currentQuiz = quizData; 
    currentQuestionIndex = 0;
    score = 0;
    
    resetQuizBody();
    quizModal.style.display = 'block';
    quizModal.scrollTop = 0;
    document.getElementById('quiz-body').style.display = 'block';
    nextBtn.style.display = 'none';
    
    loadQuestion();
}

function nextQuestion() {
    if (!isAnswered) return;
    currentQuestionIndex++;
    if (currentQuestionIndex < currentQuiz.length) {
        loadQuestion();
    } else {
        showQuizResult();
    }
}

function loadQuestion() {
    isAnswered = false;
    nextBtn.style.display = 'none';
    const qData = currentQuiz[currentQuestionIndex];
    currentQNum.innerText = currentQuestionIndex + 1;
    totalQNum.innerText = currentQuiz.length;
    quizQuestion.innerText = qData.q;
    
    quizOptions.innerHTML = '';
    qData.options.forEach((opt, index) => {
        const btn = document.createElement('button');
        btn.className = 'quiz-option';
        btn.innerText = opt;
        btn.onclick = () => selectAnswer(index, btn, qData.ans);
        quizOptions.appendChild(btn);
    });
}

function selectAnswer(selectedIndex, btnElement, correctIndex) {
    if(isAnswered) return;
    isAnswered = true;
    
    const allBtns = quizOptions.children;
    if(selectedIndex === correctIndex) {
        btnElement.classList.add('correct');
        score++;
    } else {
        btnElement.classList.add('wrong');
        allBtns[correctIndex].classList.add('correct');
    }
    
    // Disable all options
    for(let i=0; i<allBtns.length; i++) {
        allBtns[i].style.cursor = 'not-allowed';
    }
    
    nextBtn.style.display = 'inline-block';
    if(currentQuestionIndex === currentQuiz.length - 1) {
        nextBtn.innerText = 'Lihat Hasil';
    } else {
        nextBtn.innerText = 'Lanjut \u00BB';
    }
}

function showQuizResult() {
    let message = '';
    let percentage = (score / currentQuiz.length) * 100;
    if(percentage === 100) {
        message = 'Luar biasa! Kamu menjawab semua dengan benar! 🏆';
    } else if (percentage >= 70) {
        message = 'Kerja bagus! Terus tingkatkan belajarmu ya! 👍';
    } else {
        message = 'Jangan menyerah! Ayo pelajari lagi ceritanya dan coba lagi! 💪';
    }
    
    const finalHtml = `
        <div class="quiz-result-container">
            <h2>Kuis Selesai! 🎉</h2>
            <div class="quiz-result-score">${score} / ${currentQuiz.length}</div>
            <p style="font-size: 1.2rem; margin-bottom: 20px;">${message}</p>
            <button class="action-btn" onclick="startQuiz()">🔄 Coba Lagi</button>
            <button class="action-btn" onclick="closeQuiz()">Tutup</button>
        </div>
    `;
    quizQuestion.innerHTML = '';
    quizOptions.innerHTML = '';
    nextBtn.style.display = 'none';
    
    document.getElementById('quiz-body').innerHTML = finalHtml;
}

function resetQuizBody() {
    // Reset body content to original for next load
    document.getElementById('quiz-body').innerHTML = `
        <h3 id="quiz-question" class="quiz-question-text">Pertanyaan akan muncul di sini...</h3>
        <div id="quiz-options" class="quiz-options-container"></div>
    `;
    // Re-bind elements since they were overwritten
    quizQuestion = document.getElementById('quiz-question');
    quizOptions = document.getElementById('quiz-options');
}

function closeQuiz() {
    quizModal.style.display = 'none';
    resetQuizBody();
}